begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table content_fixture(course uuid,unit uuid,lesson uuid,activity uuid,assessment uuid,completion uuid);grant select,insert,update on content_fixture to cuevo_api;
insert into content_fixture(course,unit,lesson,activity,assessment)values('99560000-0000-4000-8000-000000000001','99570000-0000-4000-8000-000000000001','99580000-0000-4000-8000-000000000001','99590000-0000-4000-8000-000000000001','995a0000-0000-4000-8000-000000000001');
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001',(select course from content_fixture),'30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Original course','Original description','PUBLISHED');
insert into app.units(school_id,id,course_id,title,sequence)values('10000000-0000-4000-8000-000000000001',(select unit from content_fixture),(select course from content_fixture),'Original unit',1);insert into app.lessons(school_id,id,unit_id,title,sequence,body)values('10000000-0000-4000-8000-000000000001',(select lesson from content_fixture),(select unit from content_fixture),'Original lesson',1,'Original lesson body');insert into app.activities(school_id,id,lesson_id,title,kind,instructions,sequence)values('10000000-0000-4000-8000-000000000001',(select activity from content_fixture),(select lesson from content_fixture),'Original practice','practice','Original checking step',1);
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.learning_content_command('draft','lesson',(select lesson from content_fixture),'{"resource":"lesson","expectedRevision":1,"title":"Private revised lesson","content":"Revised lesson text","kind":null,"assessmentId":null,"reason":"Teacher prepares revision"}','content-draft',repeat('a',64),'content-test')is not null as draft;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is(internal.read_learning_content('lesson',(select lesson from content_fixture),false,'{"limit":25}')->>'content','Original lesson body','learner keeps published content while new draft private');
select throws_ok($$select internal.learning_content_command('publish','lesson',(select lesson from content_fixture),'{"expectedRevision":2,"confirmPublication":true}','content-learner-publish',repeat('b',64),'content-test')$$,'42501',null,'learner cannot publish content revision');
update content_fixture set completion=gen_random_uuid();insert into app.activity_completions(school_id,id,activity_id,learner_id)values('10000000-0000-4000-8000-000000000001',(select completion from content_fixture),(select activity from content_fixture),'20000000-0000-4000-8000-000000000012');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select throws_ok($$select internal.learning_content_command('publish','lesson',(select lesson from content_fixture),'{"expectedRevision":1,"confirmPublication":true}','content-stale-publish',repeat('b',64),'content-test')$$,'22023',null,'stale content publication denied');
select internal.learning_content_command('publish','lesson',(select lesson from content_fixture),'{"expectedRevision":2,"confirmPublication":true}','content-publish',repeat('c',64),'content-test')is not null as published;
select lives_ok($$select internal.learning_content_command('publish','lesson',(select lesson from content_fixture),'{"expectedRevision":2,"confirmPublication":true}','content-publish',repeat('c',64),'content-test')$$,'original publication key reconciles one exact content source');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is(internal.read_learning_content('lesson',(select lesson from content_fixture),false,'{"limit":25}')->>'content','Revised lesson text','learner sees explicitly published revision');
reset role;select is((select r.content from app.learning_completion_context context join app.learning_content_revisions r on r.school_id=context.school_id and r.id=context.lesson_revision_id where context.completion_id=(select completion from content_fixture)),'Original lesson body','existing completion pins old lesson content after publication');
select is((select body from app.lessons where id=(select lesson from content_fixture)),'Original lesson body','stable identity original source remains unchanged');
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select throws_ok($$select internal.read_learning_content_set(jsonb_build_array(jsonb_build_object('resource','lesson','id',(select lesson from content_fixture)),jsonb_build_object('resource','lesson','id',(select lesson from content_fixture))))$$,'22023',null,'duplicate bounded content source tuples rejected');
select is(internal.read_learning_source_context('completion',(select completion from content_fixture))->'lesson'->>'content','Original lesson body','exact completion source context remains original after new publication');
select internal.learning_content_command('retire','lesson',(select lesson from content_fixture),'{"expectedRevision":3,"reason":"Teacher retires current material","confirmRetirement":true}','content-retire',repeat('d',64),'content-test')is not null as retired;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);select throws_ok($$select internal.read_learning_content('lesson',(select lesson from content_fixture),false,'{"limit":25}')$$,'42501',null,'retired content is not offered as current learner source');
select ok(not has_table_privilege('cuevo_api','app.learning_content_revisions','select'),'raw content revision history stays private');select ok(not has_table_privilege('authenticated','app.learning_completion_context','select'),'browser cannot read raw source snapshots');
reset role;select is((select count(*)from app.learning_content_revisions where source_id=(select lesson from content_fixture)),4::bigint,'draft publication retirement retain exact source history');select*from finish();rollback;

